/// Write a rsthon function to check whether the given vector is monotonic or not.
fn is_Monotonic(A: Vec<isize>) -> bool {
    let mut is_increasing = true;
    let mut is_decreasing = true;
    for i in 0..A.len() - 1 {
        if A[i] > A[i + 1] {
            is_increasing = false;
        }
        if A[i] < A[i + 1] {
            is_decreasing = false;
        }
    }
    is_increasing || is_decreasing}

