def is_sublist(l, s):
	sub_set = False
	if s == []:
		sub_set = True
	elif s == l:
		sub_set = True
	elif len(s) > len(l):
		sub_set = False
	else:
		for i in range(len(l)):
			if l[i] == s[0]:
				n = 1
				while (n < len(s)) and (l[i+n] == s[n]):
					n += 1				
				if n == len(s):
					sub_set = True
	return sub_set

rust_solution:
/// Write a function to check whether a vector contains the given subvector or not.
fn is_sublist(l: Vec<isize>, s: Vec<isize>) -> bool {
    let mut sub_set = false;
    if s == [] {
        sub_set = true;
    } else if s == l {
        sub_set = true;
    } else if s.len() > l.len() {
        sub_set = false;
    } else {
        for i in 0..l.len() {
            if l[i] == s[0] {
                let mut n = 1;
                while n < s.len() && l[i + n] == s[n] {
                    n += 1;
                }
                if n == s.len() {
                    sub_set = true;
                }
            }
        }
    }
    sub_set}

