def lps(str): 
	n = len(str) 
	L = [[0 for x in range(n)] for x in range(n)] 
	for i in range(n): 
		L[i][i] = 1
	for cl in range(2, n+1): 
		for i in range(n-cl+1): 
			j = i+cl-1
			if str[i] == str[j] and cl == 2: 
				L[i][j] = 2
			elif str[i] == str[j]: 
				L[i][j] = L[i+1][j-1] + 2
			else: 
				L[i][j] = max(L[i][j-1], L[i+1][j]); 
	return L[0][n-1]

rust_solution:
/// Write a function to find the length of the longest palindromic subsequence in the given string.
fn lps(str: String) -> isize {
    let n = str.len();
    let mut L = vec![vec![0; n]; n];
    for i in 0..n {
        L[i][i] = 1;
    }
    for cl in 2..=n {
        for i in 0..n - cl + 1 {
            let j = i + cl - 1;
            if str.as_bytes()[i] == str.as_bytes()[j] {
                L[i][j] = L[i + 1][j - 1] + 2;
            } else {
                L[i][j] = std::cmp::max(L[i][j - 1], L[i + 1][j]);
            }
        }
    }
    L[0][n - 1]}

