    let mut char_order: Vec<char> = Vec::new();
    let mut ctr: std::collections::HashMap<char, i32> = std::collections::HashMap::new();
    for c in str1.chars() {
        if ctr.contains_key(&c) {
            ctr.insert(c, ctr.get(&c).unwrap() + 1);
        } else {
            ctr.insert(c, 1);
            char_order.push(c);
        }
    }
    for c in char_order {
        if ctr.get(&c).unwrap() == &1 {
            return Some(c.to_string());
        }
    }
    None}

